//! `afg agents sync`: generate agent configuration from the policy.
//!
//! Everything this writes is defense in depth for *integration mode*. Only
//! `afg run` enforces policy itself (docs/security-boundaries.md).

use std::path::Path;
use std::process::ExitCode;

use afg_core::paths::{DEFAULT_GLOBS, DEFAULT_HOME_PATHS};
use afg_core::{Effect, Policy};
use anyhow::Context;
use serde_json::{Value, json};

use crate::project;

pub const BEGIN: &str =
    "<!-- agentforge:begin (generated by `afg agents sync`; edits inside are overwritten) -->";
pub const END: &str = "<!-- agentforge:end -->";

#[derive(Debug, clap::Subcommand)]
pub enum AgentsCommand {
    /// Write agent configuration derived from agentforge.yaml.
    Sync {
        #[arg(value_enum)]
        agent: AgentTarget,
        /// Print what would be written instead of writing it.
        #[arg(long)]
        dry_run: bool,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, clap::ValueEnum)]
pub enum AgentTarget {
    Claude,
    Codex,
}

pub fn run(cmd: AgentsCommand) -> anyhow::Result<ExitCode> {
    let AgentsCommand::Sync { agent, dry_run } = cmd;
    let cwd = std::env::current_dir()?.canonicalize()?;
    let p = project::load(&cwd)?;
    let policy = p.engine.policy();
    let files: Vec<(std::path::PathBuf, String)> = match agent {
        AgentTarget::Claude => {
            let settings_path = p.root.join(".claude/settings.json");
            let existing = std::fs::read_to_string(&settings_path).ok();
            let settings = claude_settings(policy, existing.as_deref())?;
            let md_path = p.root.join("CLAUDE.md");
            let md = upsert_section(
                std::fs::read_to_string(&md_path).ok().as_deref(),
                &instructions(policy, "Claude Code"),
            );
            vec![(settings_path, settings), (md_path, md)]
        }
        AgentTarget::Codex => crate::agents::codex_files(&p.root, policy)?,
    };
    for (path, content) in files {
        if dry_run {
            println!("==> {} <==\n{content}", path.display());
            continue;
        }
        if std::fs::read_to_string(&path).ok().as_deref() == Some(content.as_str()) {
            eprintln!("afg: unchanged {}", path.display());
            continue;
        }
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(&path, &content).with_context(|| format!("writing {}", path.display()))?;
        eprintln!("afg: wrote {}", path.display());
    }
    Ok(ExitCode::SUCCESS)
}

/// The shared instruction text for CLAUDE.md and AGENTS.md. Both files are
/// generated from this one template (T8.2).
pub fn instructions(policy: &Policy, agent: &str) -> String {
    let mut deny = Vec::new();
    let mut ask = Vec::new();
    let mut route = Vec::new();
    for r in &policy.rules {
        let cmds: Vec<String> = r
            .commands
            .iter()
            .map(|c| format!("`{}`", c.join(" ")))
            .collect();
        match r.effect {
            Effect::Deny => deny.extend(cmds),
            Effect::RequireApproval => ask.extend(cmds),
            Effect::Route => route.extend(cmds),
            Effect::Allow => {}
        }
    }
    let list = |v: &[String]| {
        if v.is_empty() {
            "(none)".to_owned()
        } else {
            v.join(", ")
        }
    };
    format!(
        "{BEGIN}\n\
## AgentForge Guard\n\
\n\
This repository is governed by `agentforge.yaml` (policy `{}`). These instructions are for {agent}; the policy, not this text, is what is enforced.\n\
\n\
- Run scripts, generated shell code and anything untrusted through afg: `afg run -- <command>`. afg routes them to an isolated container.\n\
- Check a command first with `afg policy explain -- <command>`. Do not try to work around a denial; ask the user instead.\n\
- Never read or print credential files ({}).\n\
- Denied: {}.\n\
- Needs human approval: {}.\n\
- Runs in a container: {}.\n\
{END}\n",
        policy.project.name,
        DEFAULT_GLOBS
            .iter()
            .take(6)
            .map(|g| format!("`{g}`"))
            .collect::<Vec<_>>()
            .join(", ")
            + ", `~/.ssh`, `~/.aws`, `~/.kube`",
        list(&deny),
        list(&ask),
        list(&route),
    )
}

/// Insert or replace the generated section, leaving the rest of the file alone.
pub fn upsert_section(existing: Option<&str>, section: &str) -> String {
    match existing {
        None => section.to_owned(),
        Some(s) => match (s.find(BEGIN), s.find(END)) {
            (Some(b), Some(e)) if e > b => format!(
                "{}{section}{}",
                &s[..b],
                s[e + END.len()..].trim_start_matches('\n')
            ),
            _ => {
                let sep = if s.is_empty() || s.ends_with("\n\n") {
                    ""
                } else if s.ends_with('\n') {
                    "\n"
                } else {
                    "\n\n"
                };
                format!("{s}{sep}{section}")
            }
        },
    }
}

/// Claude Code permission rules for protected paths (Read and Edit deny).
pub fn protected_path_rules(policy: &Policy) -> Vec<String> {
    let mut patterns: Vec<String> = DEFAULT_HOME_PATHS
        .iter()
        .map(|p| {
            let is_file = p.contains("credentials")
                || p.starts_with(".netrc")
                || p.starts_with(".git-")
                || p.ends_with("rc");
            if is_file {
                format!("~/{p}")
            } else {
                format!("~/{p}/**")
            }
        })
        .collect();
    patterns.extend(DEFAULT_GLOBS.iter().map(|g| format!("**/{g}")));
    for extra in &policy.protected_paths {
        if extra.starts_with('~') {
            patterns.push(
                extra.trim_end_matches('/').to_owned()
                    + if extra.ends_with('/') { "/**" } else { "" },
            );
        } else if extra.contains('/') {
            patterns.push(
                format!("./{}", extra.trim_start_matches("./").trim_end_matches('/'))
                    + if extra.ends_with('/') { "/**" } else { "" },
            );
        } else {
            patterns.push(format!("**/{extra}"));
        }
    }
    let mut out = Vec::new();
    for pat in patterns {
        out.push(format!("Read({pat})"));
        out.push(format!("Edit({pat})"));
    }
    out
}

/// `Bash(...)` rules mirroring the policy's deny and approval rules.
pub fn bash_rules(policy: &Policy) -> (Vec<String>, Vec<String>) {
    let mut deny = Vec::new();
    let mut ask = Vec::new();
    for r in &policy.rules {
        let target = match r.effect {
            Effect::Deny => &mut deny,
            Effect::RequireApproval => &mut ask,
            _ => continue,
        };
        for c in &r.commands {
            if c.iter().any(|w| w.contains(['(', ')']) || w.contains('/')) {
                continue;
            }
            let rule = format!("Bash({} *)", c.join(" "));
            if !target.contains(&rule) {
                target.push(rule);
            }
        }
    }
    (deny, ask)
}

fn hook_entry(matcher: &str, args: &[&str]) -> Value {
    json!({
        "matcher": matcher,
        "hooks": [{ "type": "command", "command": "afg", "args": args, "timeout": 60 }]
    })
}

fn is_afg_hook(v: &Value) -> bool {
    v["hooks"].as_array().is_some_and(|hs| {
        hs.iter()
            .any(|h| h["command"] == "afg" && h["args"].get(0).is_some_and(|a| a == "hook"))
    })
}

fn merge_unique(arr: &mut Value, items: &[String]) {
    if !arr.is_array() {
        *arr = json!([]);
    }
    let a = arr.as_array_mut().expect("array");
    for i in items {
        if !a.iter().any(|x| x == i) {
            a.push(json!(i));
        }
    }
}

/// Merge afg's rules and hooks into `.claude/settings.json`. Other keys and
/// rules are preserved, and running it again changes nothing.
pub fn claude_settings(policy: &Policy, existing: Option<&str>) -> anyhow::Result<String> {
    let mut v: Value = match existing {
        Some(s) if !s.trim().is_empty() => {
            serde_json::from_str(s).context("parsing .claude/settings.json")?
        }
        _ => json!({}),
    };
    anyhow::ensure!(
        v.is_object(),
        ".claude/settings.json must hold a JSON object"
    );
    let (bash_deny, bash_ask) = bash_rules(policy);
    let mut deny = protected_path_rules(policy);
    deny.extend(bash_deny);
    merge_unique(&mut v["permissions"]["deny"], &deny);
    merge_unique(&mut v["permissions"]["ask"], &bash_ask);

    for (event, matcher, args) in [
        ("PreToolUse", "Bash", vec!["hook", "claude-pretool"]),
        (
            "PostToolUse",
            "Edit|Write|MultiEdit",
            vec!["hook", "claude-posttool-format"],
        ),
    ] {
        let list = &mut v["hooks"][event];
        if !list.is_array() {
            *list = json!([]);
        }
        let a = list.as_array_mut().expect("array");
        a.retain(|e| !is_afg_hook(e) || e["matcher"] != matcher);
        a.push(hook_entry(matcher, &args));
    }
    Ok(serde_json::to_string_pretty(&v)? + "\n")
}

/// Codex files (T8.1).
pub fn codex_files(
    _root: &Path,
    _policy: &Policy,
) -> anyhow::Result<Vec<(std::path::PathBuf, String)>> {
    anyhow::bail!("`afg agents sync codex` is not implemented yet")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn policy() -> Policy {
        Policy::from_yaml(afg_core::builtin::policy_source("default").unwrap()).unwrap()
    }

    #[test]
    fn settings_contain_rules_and_hooks() {
        let s = claude_settings(&policy(), None).unwrap();
        let v: Value = serde_json::from_str(&s).unwrap();
        let deny: Vec<&str> = v["permissions"]["deny"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap())
            .collect();
        for r in [
            "Read(~/.ssh/**)",
            "Edit(~/.ssh/**)",
            "Read(**/.env)",
            "Read(**/*.pem)",
            "Read(~/.netrc)",
            "Bash(terraform destroy *)",
            "Bash(kubectl delete *)",
        ] {
            assert!(deny.contains(&r), "missing {r}");
        }
        let ask: Vec<&str> = v["permissions"]["ask"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap())
            .collect();
        assert!(ask.contains(&"Bash(kubectl apply *)"));
        assert!(
            v["permissions"].get("allow").is_none(),
            "no allow rules are generated"
        );
        assert_eq!(
            v["hooks"]["PreToolUse"][0]["hooks"][0]["args"],
            json!(["hook", "claude-pretool"])
        );
        assert_eq!(
            v["hooks"]["PostToolUse"][0]["matcher"],
            "Edit|Write|MultiEdit"
        );
    }

    #[test]
    fn merge_preserves_user_settings_and_is_idempotent() {
        let user = r#"{"model":"x","permissions":{"allow":["Bash(npm run lint)"],"deny":["Read(./secrets/**)"]},
            "hooks":{"PreToolUse":[{"matcher":"Write","hooks":[{"type":"command","command":"mine"}]}]}}"#;
        let once = claude_settings(&policy(), Some(user)).unwrap();
        let twice = claude_settings(&policy(), Some(&once)).unwrap();
        assert_eq!(once, twice);
        let v: Value = serde_json::from_str(&once).unwrap();
        assert_eq!(v["model"], "x");
        assert_eq!(v["permissions"]["allow"], json!(["Bash(npm run lint)"]));
        assert_eq!(v["permissions"]["deny"][0], "Read(./secrets/**)");
        assert_eq!(v["hooks"]["PreToolUse"].as_array().unwrap().len(), 2);
    }

    #[test]
    fn rejects_non_object_settings() {
        assert!(claude_settings(&policy(), Some("[]")).is_err());
        assert!(claude_settings(&policy(), Some("{oops")).is_err());
    }

    #[test]
    fn section_upsert() {
        let sec = instructions(&policy(), "Claude Code");
        assert!(sec.contains("terraform destroy") && sec.contains("afg run --"));
        assert_eq!(upsert_section(None, &sec), sec);
        let with = upsert_section(Some("# Project\n\nNotes.\n"), &sec);
        assert!(with.starts_with("# Project\n\nNotes.\n\n<!-- agentforge:begin"));
        let replaced = upsert_section(Some(&with), &sec.replace("Denied", "DENIED"));
        assert_eq!(replaced.matches(BEGIN).count(), 1);
        assert!(replaced.contains("DENIED") && replaced.starts_with("# Project"));
        assert_eq!(
            upsert_section(Some(&replaced), &sec.replace("Denied", "DENIED")),
            replaced
        );
    }
}
